int my_atoi(char* str) {
    int sign = 1, result = 0;
    while(*str && isspace(*str)) str++;
    if (*str == '-') {
        sign = -1;
        str++;
    }
    while (isdigit(*str)) {
        result = result * 10 + (*str - '0');
        str++;
    }
    return sign * result;
}

