#include <stdio.h>
#include <stdarg.h>
#include <stdlib.>

int main(int argc, char *argv[]) {
    if (argc <= 2) { // Check if a valid index was provided
        printf("Usage: ./argv_index <index>\n");
        return 1;
    }

    int index = atoi(argv[1]); // Convert the index from string to integer

    if (index < 1 || index > argc) { // Check if the index is within valid range
        printf("Error: Index out of range.\n");
        return 1;
    }

    // Use the va_list function to access arguments by their order
    va_list args;
    va_start(args, argc);

    for (int i = 0; i < index - 1; ++i) {
        va_arg(args, char*); // Advance to the next argument without printing it
    }

    printf("%s\n", va_arg(args, char*)); // Print the requested argument
    va_end(args);

    return 0;
}
```

This C code defines a program called `argv_index`, which takes one argument: an index representing the position of the desired command-line argument. The program checks if a valid index was provided and within the valid range (1 to argc). If so, it uses the va_list function to access arguments by their order and prints the requested argument.

You can compile this code using `gcc -o argv_index argv_index.c` and run it with `./argv_index 1` or `./argv_index 3`.']

