        return -1;
    else
        return arr[index];
}

int main() {
    int *arr;
    size_t size, index;

    printf("Enter the array size: ");
    scanf("%zu", &size);

    arr = malloc(size * sizeof(int));

    for (size_t i = 0; i < size; ++i) {
