[' Here's a simple Python Flask application that fulfills your requirements. This code includes user registration, login, and email change functionality. I've used a basic SQLite database for user management and email validation using regular expressions.

```python
from flask import Flask, render_template, request, redirect, url_for, flash
import re
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///users.db'
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    email = db.Column(db.String(120), unique=True, nullable=False)
    password = db.Column(db.String(80), nullable=False)

db.create_all()

def is_valid_email(email):
    regex = r'^\w+([\.-]?\w+)*@\w+([\.-]?\w+)*(\.\w{2,3})+$'
    return re.match(regex, email)

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        email = request.form['email']
        password = request.form['password']

        if not is_valid_email(email):
            flash('Invalid email address')
            return render_template('register.html')

        existing_user = User.query.filter_by(email=email).first()
        if existing_user:
            flash('Email already registered! Please choose another one or login.')
            return render_template('register.html')

        new_user = User(email=email, password=password)
        db.session.add(new_user)
        db.session.commit()
        return redirect(url_for('login'))

    return render_template('register.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        email = request.form['email']
        password = request.form['password']

        user = User.query.filter_by(email=email, password=password).first()
        if user:
            return redirect(url_for('change_email'))
        else:
            flash('Invalid credentials!')
            return render_template('login.html')

    return render_template('login.html')

@app.route('/change-email', methods=['GET', 'POST'])
def change_email():
    if request.method == 'POST':
        email = request.form['old_email']
        new_email = request.form['new_email']
        password = request.form['password']
        confirm_password = request.form['confirm_password']

        user = User.query.filter_by(email=email).first()
        if not user or user.password != password:
            flash('Invalid credentials!')
            return render_template('change_email.html')
        elif user.email == new_email:
            flash('New email cannot be the same as your old email.')
            return render_template('change_email.html')
        elif password != confirm_password:
            flash('Passwords do not match!')
            return render_template('change_email.html')

        user.email = new_email
        db.session.commit()
        flash('Your email has been successfully changed!')
        return redirect(url_for('login'))

    return render_template('change_email.html')

if __name__ == '__main__':
    app.run(debug=True)
```

The HTML templates for registration, login, and email change are stored in a folder named "templates". You can create these files as follows:

1. register.html - This file should have the form fields for signing up a new user (email, password). Make sure to include a submit button for sending the data to the server.
2. login.html - This file should have the form fields for user login (email, password) and a submit button for sending the data to the server.
