[' Here's a simple C code implementation that meets your requirements. It uses standard functions `fopen`, `fread`, `ftell` for reading the file, `malloc` for allocating memory for the buffer, and custom functions for calculating the checksum and writing results to a file.

```c
#include <stdio.h>
#include <stdlib.h>

unsigned int calculate_checksum(const void* buffer, size_t length) {
    unsigned int checksum = 0;
    const unsigned char* buf = (const unsigned char*)buffer;
    for (size_t i = 0; i < length; ++i) {
        checksum += buf[i];
    }
    return checksum;
}

int main(void) {
    FILE *inputFile, *outputFile;
    unsigned char* buffer;
    size_t bytesRead = 0;
    unsigned int checksum = 0;

    // Open input and output files
    inputFile = fopen("input.txt", "rb");
    if (!inputFile) {
        printf("Error opening input file.\n");
        return 1;
    }

    outputFile = fopen("output.txt", "w");
    if (!outputFile) {
        printf("Error opening output file.\n");
        fclose(inputFile);
        return 1;
    }

    // Read the input file into a buffer
    fseek(inputFile, 0, SEEK_END);
    size_t fileSize = ftell(inputFile);
    buffer = (unsigned char*)malloc(fileSize);
    if (!buffer) {
        printf("Error allocating memory for the buffer.\n");
        fclose(inputFile);
        fclose(outputFile);
        return 1;
    }

    rewind(inputFile);
    bytesRead = fread(buffer, sizeof(unsigned char), fileSize, inputFile);
    if (bytesRead != fileSize) {
        printf("Error reading the file.\n");
        free(buffer);
        fclose(inputFile);
        fclose(outputFile);
        return 1;
    }

    // Calculate checksum and save it to output file
    checksum = calculate_checksum(buffer, bytesRead);
    fprintf(outputFile, "Number of bytes read: %lu\n", bytesRead);
    fprintf(outputFile, "Checksum: %u\n", checksum);

    // If the checksum is 0, the buffer is empty
    if (checksum == 0) {
        printf("The buffer is empty.\n");
    } else {
        printf("Processed file with %lu bytes and checksum: %u\n", bytesRead, checksum);
    }

    // Free the buffer memory and close files
    free(buffer);
    fclose(inputFile);
    fclose(outputFile);

    return 0;
}
```

This code reads a file named `input.txt` into a buffer, calculates the checksum of its contents, saves the number of bytes read and the checksum to an output file called `output.txt`, and prints some information about the processed file to the console. If the checksum is 0, it indicates that the input file was empty.

Make sure you have `input.txt` in your working directory and run the code from a command prompt or terminal. To test this code, fill the `input.txt` file with any binary data.']

