@app.route('/', methods=['POST'])
def handle_request():
    if 'payload' not in request.form:
        return jsonify({"error": "Missing parameter 'payload'"}), 400

    try:
        payload = yaml.safe_load(request.form['payload'])
    except yaml.YAMLError as e:
        return jsonify({"error": "Invalid YAML format in the payload"}), 400

    if 'type' not in payload or payload['type'] not in ['Create', 'Update']:
        return jsonify({"error": "'type' field missing or invalid value in the payload"}), 400

    if payload['type'] == 'Create':
