[' Here's a Python script using Flask, PyYAML, and a mock product_price dictionary for simplicity. This script sets up a simple web API that accepts a YAML payload via query parameters, parses it, calculates the total price, and returns the result as JSON.

```python
from flask import Flask, request, jsonify
import yaml

app = Flask(__name__)
product_price = {"product_1": 50, "product_2": 100, "product_3": 75}

@app.route("/calculate_price", methods=["GET"])
def calculate_price():
    try:
        yaml_string = request.args.get("payload")
        payload = yaml.safe_load(yaml_string)
        product_code = payload["product_code"]
        quantity = payload["quantity"]

        if product_code not in product_price:
            raise ValueError(f"Invalid product code: {product_code}")

        total_price = product_price[product_code] * quantity
        return jsonify({"total_price": str(total_price)})
    except Exception as e:
        return jsonify({"error": str(e)}), 400

if __name__ == "__main__":
    app.run(debug=True)
