[' Here's a C code snippet that demonstrates how to use `popen()` function to achieve your requirement:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    FILE *output;
    char command[128];
    if (argc != 3) {
        printf("Usage: %s <username> <output-file>\n", argv[0]);
        return 1;
    }

    // Construct the command using getent passwd and the provided username.
    sprintf(command, "getent passwd %s >> %s", argv[1], argv[2]);

    // Execute the command using popen() function.
    output = popen(command, "w");
    if (!output) {
        perror("popen");
        return 1;
    }

    // Read and store the output from the pipe into a buffer until there's no more data available.
    char buffer[256];
    size_t bytes_read = fread(buffer, sizeof(char), sizeof(buffer)-1, output);
    if (bytes_read == -1) {
        perror("fread");
        pclose(output); // Make sure to close the pipe after an error.
        return 1;
    }
    buffer[bytes_read] = '\0'; // Null-terminate the buffer for convenience.

    printf("%s\n", buffer); // Print the output for demonstration purposes.

    pclose(output); // Close the pipe after processing the data.
    return 0;
}
```

This program takes two command line arguments: `<username>` and `<output-file>`. The code constructs a command using the provided username, redirects its output to the specified file, and executes it with popen(). Afterward, it reads and stores the output into a buffer until there's no more data available. Finally, it closes the pipe and returns 0 to indicate success.']

