void exec_command(char *command) {
    FILE *pipe = popen(command, "r");
    char buffer[128];
    size_t i = 0;
    while (fgets(buffer, sizeof(buffer), pipe)) {
        fputs(buffer, stdout);
        i = 0;
    }
    pclose(pipe);
}

