```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Error: Exactly one argument is required.\n");
        return 1;
    }

    // Check if the provided argument is a string
    if (!strcmp(argv[1], "(not a string)")) {
        printf("Error: Argument must be a string.\n");
        return 1;
    }

    char *arg = argv[1];

    // Trim trailing whitespace
    size_t len = strlen(arg);
    for (size_t i = len - 1; i > 0; --i) {
        if (!isspace((unsigned char)arg[i])) {
            arg[len] = '\0';
            break;
        }
        arg[len - 1] = '\0';
    }

    // Trim newlines
    for (size_t i = 0; arg[i]; ++i) {
        if (arg[i] == '\n') {
            size_t j = i + 1;
            while (arg[j]) j++;
            memmove(&arg[0], &arg[i + 1], j - (i + 1));
            arg[j - (i + 1)] = '\0';
            --i;
        }
    }

    // Null terminate the string
    if (!*arg) {
        printf("Error: Argument is empty.\n");
        return 1;
