#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void http_hello_page(FILE *request, FILE *response) {
    char username[256]; // assuming the username is not longer than 255 characters

    // read the username from the request
    fscanf(request, "%255s", username);

    // escape the username using escape_html function
    char escaped_username[256];
    strcpy(escaped_username, username);
    escape_html(escaped_username);

    // construct and send the response
    fprintf(response, "HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=UTF-8\r\nConnection: close\r\n\r\n");
    fprintf(response, "<!DOCTYPE html>\n<html lang='en'>\n<head>\n  <meta charset='UTF-8'>\n  <title>Hello Page</title>\n</head>\n<body>\n  <h1>Hello, %s!</h1>\n</body>\n</html>", escaped_username);
}
```

Make sure to implement the `escape_html()` function according to the HTML escape specifications:

- Replace `&` with `&amp;`
- Replace `<` with `&lt;`
- Replace `>` with `&gt;`
- Replace `"` with `&quot;`
- Replace `'` with `&apos;`

This implementation assumes that the server sends a Content-Length header and sets the connection to close, so it does not need to keep track of the number of bytes sent. If this is not the case, you will need to add appropriate modifications to handle the length of the response.']

