    'templates': {
        'home': '<h1>Welcome to {{ name }}!</h1>'
    }
}

def render_response_from_env(request, env):
    template_name = request.args.get('template')
    template = env['templates'][template_name]

    # Assuming the environment also contains a context dictionary with 'name' as a key
    context = {
        'name': request.args.get('name', 'World')
    }

    tenv = jinja2.Environment(loader=jinja2.DictLoader([context]))
    rendered_template = tenv.from_string(template).render()

    response = Response(rendered_template)
    return response

